<?php
namespace Modules\Academy\Services;
use Core\database\DB;use Modules\System\Services\SiteAdminAccess;use RuntimeException;
class AcademyTermService{
public function bootstrap(int $actor):array{$branches=$this->branches($actor);$bids=array_column($branches,'branch_id');$courses=$bids?DB::table('academy_branch_courses')->whereIn('branch_id',$bids)->whereNull('deleted_at')->get():[];$cids=array_column($courses,'course_id');$rooms=$bids?DB::table('academy_branch_classrooms')->whereIn('branch_id',$bids)->whereNull('deleted_at')->get():[];$terms=$cids?DB::table('academy_branch_course_terms')->whereIn('course_id',$cids)->whereNull('deleted_at')->get():[];$tids=array_column($terms,'term_id');$tr=$this->texts(['academy_branches'=>array_column($branches,'branch_id'),'academy_branch_courses'=>$cids,'academy_branch_classrooms'=>array_column($rooms,'classroom_id'),'academy_branch_course_terms'=>$tids]);$bmap=[];foreach($branches as$r)$bmap[(int)$r['branch_id']]=$tr['academy_branches'][(int)$r['branch_id']]['name']??('شعبه '.$r['branch_id']);$cmap=[];foreach($courses as$r)$cmap[(int)$r['course_id']]=$r;$members=$bids?$this->members($bids):[];$mmap=[];foreach($members as$m)$mmap[$m['id']]=$m;$people=[];if($tids)foreach(DB::table('academy_branch_course_term_enrollments')->whereIn('term_id',$tids)->whereNull('deleted_at')->get()as$e)$people[(int)$e['term_id']][]=['id'=>(int)$e['member_id'],'name'=>$mmap[(int)$e['member_id']]['name']??('عضو '.$e['member_id']),'type'=>$e['type']];$sessions=$tids?$this->sessions($tids):[];$invoices=[];if($tids)foreach(DB::table('academy_branch_course_term_invoices')->whereIn('term_id',$tids)->whereNull('deleted_at')->get()as$i)$invoices[(int)$i['term_id']]=$i;$statuses=['pending'=>'در انتظار','open'=>'باز','ongoing'=>'در حال برگزاری','finished'=>'پایان‌یافته'];return['branches'=>array_map(fn($r)=>['id'=>(int)$r['branch_id'],'name'=>$bmap[(int)$r['branch_id']]],$branches),'courses'=>array_map(fn($r)=>['id'=>(int)$r['course_id'],'branchId'=>(int)$r['branch_id'],'lessonId'=>(int)$r['lesson_id'],'name'=>$tr['academy_branch_courses'][(int)$r['course_id']]['title']??('دوره '.$r['course_id']),'teacher_capacity'=>(int)$r['teacher_capacity'],'student_capacity'=>(int)$r['student_capacity']],$courses),'classrooms'=>array_map(fn($r)=>['id'=>(int)$r['classroom_id'],'branchId'=>(int)$r['branch_id'],'name'=>$tr['academy_branch_classrooms'][(int)$r['classroom_id']]['title']??$tr['academy_branch_classrooms'][(int)$r['classroom_id']]['name']??('کلاس '.$r['classroom_id'])],$rooms),'currencies'=>$this->currencies(),'discounts'=>$this->discounts(),'members'=>$members,'terms'=>array_map(function($r)use($cmap,$bmap,$tr,$people,$sessions,$invoices,$statuses){$id=(int)$r['term_id'];$c=$cmap[(int)$r['course_id']];$p=$people[$id]??[];$s=$sessions[$id]??[];$i=$invoices[$id]??null;return['id'=>$id,'name'=>$tr['academy_branch_course_terms'][$id]['title']??('ترم '.$id),'summary'=>$tr['academy_branch_course_terms'][$id]['summary']??'','description'=>$tr['academy_branch_course_terms'][$id]['description']??'','branchId'=>(int)$c['branch_id'],'branchName'=>$bmap[(int)$c['branch_id']],'courseId'=>(int)$r['course_id'],'course'=>$tr['academy_branch_courses'][(int)$r['course_id']]['title']??('دوره '.$r['course_id']),'classroomId'=>(int)($s[0]['classroomId']??0),'currencyId'=>(int)($i['currency_id']??$r['currency_id']),'cost'=>(float)($i['payable_amount']??$r['price']),'discountId'=>(int)($i['discount_id']??0),'installmentCount'=>$i?$this->installmentCount((int)$i['term_invoice_id']):1,'repeatType'=>$r['session_period'],'status_code'=>$r['status'],'status'=>$statuses[$r['status']]??$r['status'],'sessions'=>$s,'teachers'=>array_values(array_filter($p,fn($x)=>$x['type']==='teacher')),'students'=>array_values(array_filter($p,fn($x)=>$x['type']==='student')),'start'=>$r['start_date'],'end'=>$r['end_date']];},$terms)];}
public function save(int$actor,array$d,int$id=0):array{$branch=$this->allowedBranch($actor,(int)($d['branchId']??0));$course=DB::table('academy_branch_courses')->where('course_id',(int)($d['courseId']??0))->where('branch_id',(int)$branch['branch_id'])->whereNull('deleted_at')->first();if(!$course)throw new RuntimeException('دوره متعلق به شعبه نیست.');$room=DB::table('academy_branch_classrooms')->where('classroom_id',(int)($d['classroomId']??0))->where('branch_id',(int)$branch['branch_id'])->whereNull('deleted_at')->first();if(!$room)throw new RuntimeException('کلاس متعلق به شعبه نیست.');$teachers=$this->validatePeople($d['teachers']??[],'teacher',(int)$branch['branch_id'],(int)$course['lesson_id'],(int)$course['teacher_capacity']);$students=$this->validatePeople($d['students']??[],'student',(int)$branch['branch_id'],0,(int)$course['student_capacity']);$sessions=array_values(array_filter($d['sessions']??[],fn($x)=>preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($x['date']??''))));if(!$sessions)throw new RuntimeException('تاریخ جلسات الزامی است.');$name=trim((string)($d['name']??''));if(!$name)throw new RuntimeException('نام ترم الزامی است.');$periods=['week','2-week','3-week','4-week','month','year','no-period'];$statuses=['pending','open','ongoing','finished'];$values=['course_id'=>(int)$course['course_id'],'start_date'=>$sessions[0]['date'],'end_date'=>$sessions[count($sessions)-1]['date'],'session_count'=>count($sessions),'session_period'=>in_array($d['repeatType']??'',$periods,true)?$d['repeatType']:'no-period','price'=>0,'currency_id'=>(int)($d['currencyId']??1),'status'=>in_array($d['status']??'',$statuses,true)?$d['status']:'pending','updated_by'=>$actor,'deleted_at'=>null,'deleted_by'=>null];return transaction(function()use($actor,$d,$id,$values,$name,$sessions,$teachers,$students,$room){if($id){if(!DB::table('academy_branch_course_terms')->where('term_id',$id)->whereNull('deleted_at')->first())throw new RuntimeException('ترم یافت نشد.');DB::table('academy_branch_course_terms')->where('term_id',$id)->update($values);$this->clear($id,$actor);}else$id=DB::table('academy_branch_course_terms')->insertGetId(['created_by'=>$actor]+$values);$this->setTexts($id,['title'=>$name,'summary'=>trim((string)($d['summary']??'')),'description'=>trim((string)($d['description']??''))],$actor);foreach($sessions as$s){$booking=DB::table('academy_branch_bookings')->insertGetId(['type'=>'group-class','status'=>'approved','requested_date'=>$s['date'],'created_by'=>$actor,'updated_by'=>$actor]);DB::table('academy_branch_course_term_sessions')->insert(['term_id'=>$id,'booking_id'=>$booking,'classroom_id'=>(int)$room['classroom_id'],'created_by'=>$actor,'updated_by'=>$actor]);}foreach(array_merge(array_map(fn($x)=>[$x,'teacher'],$teachers),array_map(fn($x)=>[$x,'student'],$students))as[$member,$type])DB::table('academy_branch_course_term_enrollments')->insert(['term_id'=>$id,'member_id'=>$member,'type'=>$type,'status'=>'active','joined_at'=>date('Y-m-d H:i:s'),'created_by'=>$actor,'updated_by'=>$actor]);$invoice=DB::table('academy_branch_course_term_invoices')->insertGetId(['term_id'=>$id,'discount_id'=>(int)($d['discountId']??0)?:null,'payable_amount'=>max(0,(float)($d['cost']??0)),'currency_id'=>$values['currency_id'],'status'=>'draft','due_date'=>$values['start_date'],'created_by'=>$actor,'updated_by'=>$actor]);$count=max(1,(int)($d['installmentCount']??1));$total=max(0,(float)($d['cost']??0));for($n=1;$n<=$count;$n++)DB::table('academy_branch_course_term_invoice_installments')->insert(['invoice_id'=>$invoice,'installment_number'=>$n,'amount'=>$n===$count?$total-floor($total/$count)*($count-1):floor($total/$count),'due_date'=>date('Y-m-d',strtotime($values['start_date'].' +'.($n-1).' month')),'status'=>'pending','created_by'=>$actor,'updated_by'=>$actor]);return['id'=>$id];});}
public function saveDiscount(int$actor,array$d):array{$title=trim((string)($d['title']??''));$type=($d['type']??'percentage')==='fixed'?'fixed':'percentage';$value=max(0,(float)($d['value']??0));if(!$title||$value<=0)throw new RuntimeException('عنوان و مقدار تخفیف الزامی است.');$id=DB::table('financial_system_discounts')->insertGetId(['code'=>'ADMIN-'.strtoupper(bin2hex(random_bytes(4))),'type'=>$type,'value'=>$value,'status'=>'active','start_date'=>date('Y-m-d'),'created_by'=>$actor,'updated_by'=>$actor]);$this->setGenericTexts('financial_system_discounts',$id,['title'=>$title,'summary'=>'تخفیف قابل استفاده برای شهریه ترم'], $actor);return['id'=>$id,'name'=>$title,'type'=>$type,'value'=>$value];}
public function delete(int$actor,int$id):void{$row=DB::table('academy_branch_course_terms')->where('term_id',$id)->whereNull('deleted_at')->first();if(!$row)throw new RuntimeException('ترم یافت نشد.');$course=DB::table('academy_branch_courses')->where('course_id',(int)$row['course_id'])->first();$this->allowedBranch($actor,(int)$course['branch_id']);DB::table('academy_branch_course_terms')->where('term_id',$id)->update(['deleted_at'=>date('Y-m-d H:i:s'),'deleted_by'=>$actor]);}
private function validatePeople(array$items,string$type,int$bid,int$lesson,int$cap):array{$ids=array_values(array_unique(array_filter(array_map(fn($x)=>(int)($x['id']??$x),$items))));if(count($ids)>$cap)throw new RuntimeException('تعداد افراد بیشتر از ظرفیت دوره است.');foreach($ids as$id){$m=DB::table('academy_branch_members')->where('member_id',$id)->where('branch_id',$bid)->whereNull('deleted_at')->first();if(!$m)throw new RuntimeException('عضو متعلق به شعبه نیست.');if($type==='teacher'){$c=DB::table('academy_branch_member_contracts')->where('member_id',$id)->where('type','teacher')->whereNull('deleted_at')->first();$ul=$c?DB::table('user_lessons')->where('user_lesson_id',(int)$c['user_lesson_id'])->where('lesson_id',$lesson)->whereNull('deleted_at')->first():null;if(!$ul)throw new RuntimeException('مدرس این درس را ارائه نمی‌دهد.');}}return$ids;}
private function members(array$bids):array{$sql='SELECT m.*,u.username FROM academy_branch_members m JOIN users u ON u.user_id=m.user_id WHERE m.deleted_at IS NULL AND u.deleted_at IS NULL AND m.branch_id IN ('.implode(',',array_map('intval',$bids)).')';$rows=db()->query($sql)->fetchAll();$uids=array_column($rows,'user_id');$names=[];if($uids)foreach(DB::table('translations')->where('table_name','users')->where('field','full_name')->where('locale','fa')->whereIn('table_id',$uids)->whereNull('deleted_at')->get()as$t)$names[(int)$t['table_id']]=$t['value'];$out=[];foreach($rows as$r){$c=DB::table('academy_branch_member_contracts')->where('member_id',(int)$r['member_id'])->whereNull('deleted_at')->first();$type=str_contains((string)$r['username'],'student_')?'student':($c['type']??'other');$ul=$c&&$c['user_lesson_id']?DB::table('user_lessons')->where('user_lesson_id',(int)$c['user_lesson_id'])->first():null;$out[]=['id'=>(int)$r['member_id'],'branchId'=>(int)$r['branch_id'],'name'=>$names[(int)$r['user_id']]??('عضو '.$r['member_id']),'type'=>$type,'lessonId'=>(int)($ul['lesson_id']??0)];}return$out;}
private function sessions(array$ids):array{$sql='SELECT s.term_id,s.classroom_id,b.requested_date date FROM academy_branch_course_term_sessions s JOIN academy_branch_bookings b ON b.booking_id=s.booking_id WHERE s.deleted_at IS NULL AND b.deleted_at IS NULL AND s.term_id IN ('.implode(',',array_map('intval',$ids)).') ORDER BY b.requested_date';$out=[];foreach(db()->query($sql)->fetchAll()as$r)$out[(int)$r['term_id']][]=['date'=>$r['date'],'classroomId'=>(int)$r['classroom_id']];return$out;}
private function currencies():array{$rows=DB::table('financial_system_currency')->get();$tr=$this->texts(['financial_system_currency'=>array_column($rows,'currency_id')]);return array_map(fn($r)=>['id'=>(int)$r['currency_id'],'name'=>$tr['financial_system_currency'][(int)$r['currency_id']]['title']??$r['code']],$rows);}private function discounts():array{$rows=DB::table('financial_system_discounts')->whereNull('deleted_at')->get();$tr=$this->texts(['financial_system_discounts'=>array_column($rows,'discount_id')]);return array_map(fn($r)=>['id'=>(int)$r['discount_id'],'name'=>$tr['financial_system_discounts'][(int)$r['discount_id']]['title']??$r['code'],'type'=>$r['type'],'value'=>(float)$r['value']],$rows);}private function installmentCount(int$id):int{return max(1,DB::table('academy_branch_course_term_invoice_installments')->where('invoice_id',$id)->whereNull('deleted_at')->count());}
private function clear(int$id,int$actor):void{$now=date('Y-m-d H:i:s');$ss=DB::table('academy_branch_course_term_sessions')->where('term_id',$id)->whereNull('deleted_at')->get();foreach($ss as$s)if($s['booking_id'])DB::table('academy_branch_bookings')->where('booking_id',(int)$s['booking_id'])->update(['deleted_at'=>$now,'deleted_by'=>$actor]);foreach(['academy_branch_course_term_sessions','academy_branch_course_term_enrollments','academy_branch_course_term_invoices']as$t)DB::table($t)->where('term_id',$id)->whereNull('deleted_at')->update(['deleted_at'=>$now,'deleted_by'=>$actor]);}
private function texts(array$groups):array{$out=[];foreach($groups as$table=>$ids)if($ids)foreach(DB::table('translations')->where('table_name',$table)->where('locale','fa')->whereIn('table_id',array_unique($ids))->whereNull('deleted_at')->get()as$r)$out[$table][(int)$r['table_id']][$r['field']]=$r['value'];return$out;}private function setTexts(int$id,array$v,int$a):void{$this->setGenericTexts('academy_branch_course_terms',$id,$v,$a);}private function setGenericTexts(string$t,int$id,array$v,int$a):void{foreach($v as$f=>$value){$r=DB::table('translations')->where('table_name',$t)->where('table_id',$id)->where('field',$f)->where('locale','fa')->first();$x=['value'=>$value,'version'=>1,'updated_by'=>$a,'deleted_at'=>null,'deleted_by'=>null];if($r)DB::table('translations')->where('translation_id',(int)$r['translation_id'])->update($x);else DB::table('translations')->insert(['table_name'=>$t,'table_id'=>$id,'field'=>$f,'locale'=>'fa','created_by'=>$a]+$x);}}
private function branches(int$a):array{$u=DB::table('users')->where('user_id',$a)->whereNull('deleted_at')->first();if(!$u)throw new RuntimeException('کاربر معتبر نیست.');if(SiteAdminAccess::allows($u))return DB::table('academy_branches')->whereNull('deleted_at')->get();if(($u['type']??'')==='branch')return DB::table('academy_branches')->where('user_id',$a)->whereNull('deleted_at')->get();$acs=array_merge(DB::table('academies')->where('user_id',$a)->whereNull('deleted_at')->get(),DB::table('academies')->where('created_by',$a)->whereNull('deleted_at')->get());$ids=array_values(array_unique(array_map(fn($x)=>(int)$x['academy_id'],$acs)));return$ids?DB::table('academy_branches')->whereIn('academy_id',$ids)->whereNull('deleted_at')->get():[];}private function allowedBranch(int$a,int$id):array{foreach($this->branches($a)as$b)if((int)$b['branch_id']===$id)return$b;throw new RuntimeException('دسترسی به شعبه ندارید.');}}
